-- SQL Server schema for DurpDeploy.
-- Apply files in numeric order. Timestamps are Unix seconds to match SQLite.
-- +goose Up
CREATE TABLE projects (id BIGINT IDENTITY(1,1) PRIMARY KEY, name NVARCHAR(255) NOT NULL UNIQUE, description NVARCHAR(MAX) NULL, created_at BIGINT NOT NULL DEFAULT DATEDIFF_BIG(SECOND,'1970-01-01',SYSUTCDATETIME()), lifecycle_id BIGINT NULL, slack_webhook_url NVARCHAR(MAX) NULL, notify_emails NVARCHAR(MAX) NULL, gotify_url NVARCHAR(MAX) NULL, gotify_token NVARCHAR(MAX) NULL, discord_webhook_url NVARCHAR(MAX) NULL);
CREATE TABLE environments (id BIGINT IDENTITY(1,1) PRIMARY KEY, name NVARCHAR(255) NOT NULL UNIQUE, description NVARCHAR(MAX) NULL, tags NVARCHAR(MAX) NULL, created_at BIGINT NOT NULL DEFAULT DATEDIFF_BIG(SECOND,'1970-01-01',SYSUTCDATETIME()));
CREATE TABLE steps (id BIGINT IDENTITY(1,1) PRIMARY KEY, project_id BIGINT NOT NULL, name NVARCHAR(255) NOT NULL, script_body NVARCHAR(MAX) NOT NULL, sort_order BIGINT NOT NULL DEFAULT 0, created_at BIGINT NOT NULL DEFAULT DATEDIFF_BIG(SECOND,'1970-01-01',SYSUTCDATETIME()), timeout_seconds BIGINT NOT NULL DEFAULT 0, max_retries BIGINT NOT NULL DEFAULT 0, FOREIGN KEY(project_id) REFERENCES projects(id) ON DELETE CASCADE);
CREATE TABLE variables (id BIGINT IDENTITY(1,1) PRIMARY KEY, project_id BIGINT NOT NULL, name NVARCHAR(255) NOT NULL, value NVARCHAR(MAX) NULL, environment_id BIGINT NULL, created_at BIGINT NOT NULL DEFAULT DATEDIFF_BIG(SECOND,'1970-01-01',SYSUTCDATETIME()), secret BIGINT NOT NULL DEFAULT 0, UNIQUE(name,project_id,environment_id), FOREIGN KEY(project_id) REFERENCES projects(id) ON DELETE CASCADE, FOREIGN KEY(environment_id) REFERENCES environments(id) ON DELETE CASCADE);
CREATE TABLE releases (id BIGINT IDENTITY(1,1) PRIMARY KEY, project_id BIGINT NOT NULL, version NVARCHAR(255) NOT NULL, steps_json NVARCHAR(MAX) NOT NULL, created_at BIGINT NOT NULL DEFAULT DATEDIFF_BIG(SECOND,'1970-01-01',SYSUTCDATETIME()), UNIQUE(project_id,version), FOREIGN KEY(project_id) REFERENCES projects(id));
CREATE TABLE release_variables (id BIGINT IDENTITY(1,1) PRIMARY KEY, release_id BIGINT NOT NULL, name NVARCHAR(255) NOT NULL, value NVARCHAR(MAX) NULL, environment_id BIGINT NULL, created_at BIGINT NOT NULL DEFAULT DATEDIFF_BIG(SECOND,'1970-01-01',SYSUTCDATETIME()), secret BIGINT NOT NULL DEFAULT 0, FOREIGN KEY(release_id) REFERENCES releases(id) ON DELETE CASCADE);
CREATE TABLE deployments (id BIGINT IDENTITY(1,1) PRIMARY KEY, release_id BIGINT NOT NULL, environment_id BIGINT NOT NULL, status NVARCHAR(64) NOT NULL DEFAULT 'pending', started_at BIGINT NULL, finished_at BIGINT NULL, created_at BIGINT NOT NULL DEFAULT DATEDIFF_BIG(SECOND,'1970-01-01',SYSUTCDATETIME()), forced BIGINT NOT NULL DEFAULT 0, note NVARCHAR(MAX) NULL, FOREIGN KEY(release_id) REFERENCES releases(id) ON DELETE CASCADE, FOREIGN KEY(environment_id) REFERENCES environments(id));
CREATE TABLE deployment_logs (id BIGINT IDENTITY(1,1) PRIMARY KEY, deployment_id BIGINT NOT NULL, step_name NVARCHAR(255) NULL, line NVARCHAR(MAX) NOT NULL, created_at BIGINT NOT NULL DEFAULT DATEDIFF_BIG(SECOND,'1970-01-01',SYSUTCDATETIME()), FOREIGN KEY(deployment_id) REFERENCES deployments(id) ON DELETE CASCADE);
CREATE TABLE users (id BIGINT IDENTITY(1,1) PRIMARY KEY, email NVARCHAR(320) NOT NULL UNIQUE, password_hash NVARCHAR(MAX) NOT NULL, name NVARCHAR(255) NOT NULL, role NVARCHAR(32) NOT NULL, created_at BIGINT NOT NULL DEFAULT DATEDIFF_BIG(SECOND,'1970-01-01',SYSUTCDATETIME()), updated_at BIGINT NOT NULL DEFAULT DATEDIFF_BIG(SECOND,'1970-01-01',SYSUTCDATETIME()), last_login_at BIGINT NULL);
CREATE TABLE sessions (id NVARCHAR(255) PRIMARY KEY, user_id BIGINT NOT NULL, csrf_token NVARCHAR(255) NOT NULL, created_at BIGINT NOT NULL DEFAULT DATEDIFF_BIG(SECOND,'1970-01-01',SYSUTCDATETIME()), expires_at BIGINT NOT NULL, ip_address NVARCHAR(64) NULL, user_agent NVARCHAR(MAX) NULL, FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE audit_log (id BIGINT IDENTITY(1,1) PRIMARY KEY, user_id BIGINT NULL, action NVARCHAR(255) NOT NULL, entity_type NVARCHAR(255) NOT NULL, entity_id BIGINT NULL, details NVARCHAR(MAX) NULL, created_at BIGINT NOT NULL DEFAULT DATEDIFF_BIG(SECOND,'1970-01-01',SYSUTCDATETIME()));
